/**
 * Bundles src/lib/battleRatingBoards.ts for the battle-ratings Edge Function.
 *
 * The function cannot import the app's modules the way auto-fire does: those are leaf files, and the
 * rating code reaches into squareSets, which imports JSON without import attributes and siblings
 * without file extensions. Vite takes both; Deno takes neither. So the function imports this bundle,
 * which is the very same code with those resolved - never a hand-kept copy, because a copy is how the
 * recap and the Hall of Fame would end up disagreeing about the same game.
 *
 * The output ends with RATING_CODE_VERSION, a hash of the bundle. The function folds it into the
 * snapshot's fingerprint, so deploying a changed formula re-rates the archive on the next read with
 * nobody having to clear anything.
 *
 *   node scripts/build-rating-bundle.mjs           write the bundle
 *   node scripts/build-rating-bundle.mjs --check   fail if the committed bundle is stale (npm run check)
 */
import { build } from 'rolldown'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const entry = fileURLToPath(new URL('../src/lib/battleRatingBoards.ts', import.meta.url))
const target = fileURLToPath(new URL('../supabase/functions/battle-ratings/ratingCode.generated.js', import.meta.url))

const result = await build({
  input: entry,
  write: false,
  platform: 'neutral',
  output: { format: 'esm', minify: false },
})
const chunk = result.output.find((o) => o.type === 'chunk')
if (!chunk) throw new Error('rolldown produced no chunk')

// Anything browser-only that survived tree-shaking would fail at the function's cold start, which
// is a worse place to find out than here.
for (const banned of ['import.meta.env', 'supabase-js', 'window.', 'document.', 'localStorage']) {
  if (chunk.code.includes(banned)) throw new Error(`the rating bundle references ${banned} - it must run under Deno`)
}

const version = createHash('sha256').update(chunk.code).digest('hex').slice(0, 16)
const text =
  '// @ts-self-types="./ratingCode.d.ts"\n' +
  '// GENERATED by scripts/build-rating-bundle.mjs from src/lib/battleRatingBoards.ts - do not edit.\n' +
  chunk.code +
  `\nexport const RATING_CODE_VERSION = ${JSON.stringify(version)};\n`

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : ''
  if (current !== text) {
    console.error(' FAIL  battle-ratings bundle is stale - run: node scripts/build-rating-bundle.mjs')
    process.exit(1)
  }
  console.log('  ok   battle-ratings bundle matches src/lib/battleRatingBoards.ts')
} else {
  writeFileSync(target, text)
  console.log(`wrote ${target} (${(text.length / 1024).toFixed(0)} KB, version ${version})`)
}
